-- 13: POST-FLIGHT for the Phase 2 module migrations 20261018100000 .. 20261018200000. Read-only. Every row should say ok = true.
with
fn as (select p.oid, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = any(array['agreement_accept','agreement_check_terms','agreement_close','agreement_detail','agreement_list','agreement_note','agreement_percent','agreement_propose','agreement_request','agreement_sample','agreement_side','change_member_role','chat_can_access','chat_conversations','chat_mark_read','chat_messages','chat_people','chat_pin','chat_purge_expired','chat_send','chat_start_direct','chat_user_at_venue','close_night','desk_booking_messages','desk_booking_seating','desk_cash_part','desk_cash_position','desk_cash_rows','desk_enqueue','desk_find_booking','desk_flag_payment','desk_list_flags','desk_list_handovers','desk_mark_seated','desk_receive_handover','desk_resolve_flag','desk_set_estimate','desk_submit_handover','desk_unseat','desk_verifier_summary','night_blockers','night_booking_ids','night_check','night_checklist','night_checklist_items','night_close_status','night_report','night_report_data','organizer_guest_summary','organizer_guests','owner_money','reopen_night','security_alert_act','security_alerts','security_create_task','security_has_role','security_incident_detail','security_incident_note','security_incidents','security_raise_alert','security_report_incident','security_review_incident','security_summary','security_task_act','security_tasks','stock_list','stock_move','stock_movements','stock_set_threshold','vip_add','vip_add_perk','vip_date','vip_detail','vip_end','vip_end_perk','vip_invite','vip_list','vip_lookup','vip_new_code','vip_redeem','vip_reinstate','vip_status','vip_update']::text[])),
tb as (select c.oid, c.relname, c.relrowsecurity from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and c.relname = any(array['site_agreement_notes','site_agreement_versions','site_agreements','site_booking_seating','site_cash_handovers','site_chat_conversations','site_chat_direct_members','site_chat_messages','site_chat_reads','site_night_checks','site_night_closes','site_outbox','site_payment_flags','site_security_alerts','site_security_incident_notes','site_security_incidents','site_security_tasks','site_stock_movements','site_stock_thresholds','site_vip_members','site_vip_perks','site_vip_redemptions']::text[]))
select * from (
  select 1 as n, 'functions exist (expected 83 names)' as check_name, (select count(distinct proname) from fn)::text as actual, '83' as expected, (select count(distinct proname) from fn) = 83 as ok
  union all select 2, 'tables exist (expected 22)', (select count(*) from tb)::text, '22', (select count(*) from tb) = 22
  union all select 3, 'row level security is on for every new table', (select count(*) from tb where relrowsecurity)::text, '22', (select count(*) from tb where relrowsecurity) = 22
  union all select 4, 'no new table is readable or writable by signed-in people or visitors', (select count(*) from tb where has_table_privilege('authenticated', oid, 'select,insert,update,delete') or has_table_privilege('anon', oid, 'select,insert,update,delete') or has_table_privilege('authenticated', oid, 'select') or has_table_privilege('anon', oid, 'select'))::text, '0',
         (select count(*) from tb where has_table_privilege('authenticated', oid, 'select') or has_table_privilege('anon', oid, 'select') or has_table_privilege('authenticated', oid, 'insert') or has_table_privilege('authenticated', oid, 'update') or has_table_privilege('authenticated', oid, 'delete')) = 0
  union all select 5, 'no new function is callable by anonymous visitors', (select count(*) from fn where has_function_privilege('anon', oid, 'execute'))::text, '0', (select count(*) from fn where has_function_privilege('anon', oid, 'execute')) = 0
  union all select 6, 'the app-facing functions are callable by signed-in people (66 names)', (select count(distinct proname) from fn where proname = any(array['agreement_accept','agreement_close','agreement_detail','agreement_list','agreement_note','agreement_propose','agreement_request','agreement_sample','change_member_role','chat_conversations','chat_mark_read','chat_messages','chat_people','chat_pin','chat_send','chat_start_direct','close_night','desk_booking_messages','desk_booking_seating','desk_cash_position','desk_find_booking','desk_flag_payment','desk_list_flags','desk_list_handovers','desk_mark_seated','desk_receive_handover','desk_resolve_flag','desk_set_estimate','desk_submit_handover','desk_unseat','desk_verifier_summary','night_check','night_checklist','night_close_status','night_report','organizer_guest_summary','organizer_guests','owner_money','reopen_night','security_alert_act','security_alerts','security_create_task','security_incident_detail','security_incident_note','security_incidents','security_raise_alert','security_report_incident','security_review_incident','security_summary','security_task_act','security_tasks','stock_list','stock_move','stock_movements','stock_set_threshold','vip_add','vip_add_perk','vip_detail','vip_end','vip_end_perk','vip_invite','vip_list','vip_lookup','vip_redeem','vip_reinstate','vip_update']::text[]) and has_function_privilege('authenticated', oid, 'execute'))::text, '66',
         (select count(distinct proname) from fn where proname = any(array['agreement_accept','agreement_close','agreement_detail','agreement_list','agreement_note','agreement_propose','agreement_request','agreement_sample','change_member_role','chat_conversations','chat_mark_read','chat_messages','chat_people','chat_pin','chat_send','chat_start_direct','close_night','desk_booking_messages','desk_booking_seating','desk_cash_position','desk_find_booking','desk_flag_payment','desk_list_flags','desk_list_handovers','desk_mark_seated','desk_receive_handover','desk_resolve_flag','desk_set_estimate','desk_submit_handover','desk_unseat','desk_verifier_summary','night_check','night_checklist','night_close_status','night_report','organizer_guest_summary','organizer_guests','owner_money','reopen_night','security_alert_act','security_alerts','security_create_task','security_incident_detail','security_incident_note','security_incidents','security_raise_alert','security_report_incident','security_review_incident','security_summary','security_task_act','security_tasks','stock_list','stock_move','stock_movements','stock_set_threshold','vip_add','vip_add_perk','vip_detail','vip_end','vip_end_perk','vip_invite','vip_list','vip_lookup','vip_redeem','vip_reinstate','vip_update']::text[]) and has_function_privilege('authenticated', oid, 'execute')) = 66
  union all select 7, 'the internal helpers are NOT callable by signed-in people (16 names)', (select count(*) from fn where proname = any(array['agreement_check_terms','agreement_percent','agreement_side','chat_can_access','chat_user_at_venue','desk_cash_part','desk_cash_rows','desk_enqueue','night_blockers','night_booking_ids','night_checklist_items','night_report_data','security_has_role','vip_date','vip_new_code','vip_status']::text[]) and has_function_privilege('authenticated', oid, 'execute'))::text, '0',
         (select count(*) from fn where proname = any(array['agreement_check_terms','agreement_percent','agreement_side','chat_can_access','chat_user_at_venue','desk_cash_part','desk_cash_rows','desk_enqueue','night_blockers','night_booking_ids','night_checklist_items','night_report_data','security_has_role','vip_date','vip_new_code','vip_status']::text[]) and has_function_privilege('authenticated', oid, 'execute')) = 0
  union all select 8, 'the service-role-only functions (chat_purge_expired) are not callable by signed-in people', (select count(*) from fn where proname = any(array['chat_purge_expired']::text[]) and has_function_privilege('authenticated', oid, 'execute'))::text, '0',
         (select count(*) from fn where proname = any(array['chat_purge_expired']::text[]) and has_function_privilege('authenticated', oid, 'execute')) = 0
  union all select 9, 'every new function has a fixed search_path (no hijack through a changed path)', (select count(*) from fn f join pg_proc p on p.oid = f.oid where p.proconfig is null or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%'))::text, '0',
         (select count(*) from fn f join pg_proc p on p.oid = f.oid where p.proconfig is null or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%')) = 0
) x order by n;
